  ('general', $content${"aviso":{"id":"a1","texto":"Bem-vinda à VEM! Confira no Painel se seu nível e sua modalidade estão certos.","exemplo":true},"metaSemanalPadrao":3,"frases":[],"corrida":[{"id":"c1","titulo":"Do zero aos 5 km","descricao":"8 semanas, 3 treinos por semana, alternando caminhada e corrida leve.","pdf":"","exemplo":true,"semanas":[{"id":"c1s1","liberaEm":"2026-11-02","titulo":"Semanas 1 e 2","texto":"5 min de caminhada. Depois 8 vezes: 1 min correndo + 1min30 caminhando."},{"id":"c1s2","liberaEm":"2026-11-16","titulo":"Semanas 3 e 4","texto":"5 min de caminhada. Depois 6 vezes: 2 min correndo + 1 min caminhando."},{"id":"c1s3","liberaEm":"2026-11-30","titulo":"Semanas 5 e 6","texto":"5 min de caminhada. Depois 3 vezes: 5 min correndo + 2 min caminhando."},{"id":"c1s4","liberaEm":"2026-12-14","titulo":"Semanas 7 e 8","texto":"5 min de caminhada. Corra 20 a 30 min no seu ritmo. Na última sessão, os 5 km."}]}],"alimentacao":[{"id":"n1","titulo":"Como montar um prato que sustenta","texto":"Metade do prato com legumes e verduras, um quarto com proteína e um quarto com carboidrato. Sem proibir nada.","pdf":"","pdfNome":"","exemplo":true},{"id":"n2","titulo":"Lanches práticos pra levar na bolsa","texto":"Fruta com castanhas, iogurte, ovo cozido, sanduíche simples. Ter opção à mão evita chegar faminta em casa.","pdf":"","pdfNome":"","exemplo":true}]}$content$::jsonb, true, 3, '3', 'latest-html-draft', now(), $meta${"importedFrom":"vem-app.html","exercises":88,"programs":6,"mealPlans":8,"courseModules":3,"meetings":4,"runningPlans":1}$meta$::jsonb)
